SELECT mmfrd.*, p.id AS 'project.id', p.name AS 'project.name', p.serial_number AS 'project.serial_number', p.short_name AS 'project.short_name', m.name AS monomer_name, ab.name AS area_batch_name, mbw.name AS workshop_name FROM mes_material_feeding_report_detail mmfrd LEFT JOIN contract_project p ON p.bool_delete_enum = 0 AND p.id = mmfrd.project_id LEFT JOIN plan_monomer m ON m.bool_delete_enum = 0 AND m.id = mmfrd.monomer_id LEFT JOIN plan_area_batch ab ON ab.bool_delete_enum = 0 AND ab.id = mmfrd.area_batch_id LEFT JOIN mes_building_workshop mbw ON mbw.bool_delete_enum = 0 AND mbw.id = mmfrd.workshop_id WHERE mmfrd.bool_delete_enum = 0 AND mmfrd.material_feeding_report_id IN (
#{materialFeedingReportId}
)

SELECT
mmfrd.*
FROM mes_material_feeding_report_detail mmfrd
where  mmfrd.bool_delete_enum = 0

    AND mmfrd.workshop_id=#{workshopId}


    AND mmfrd.structure_type = #{structureType}
